#include <iostream>
#include <sstream>
#include <string>
#include <cstring>

// Trivially Copyable struct with fixed array buffer
struct StudentRecord {
    char name[32];
    int age;
    double score;
};

int main() {
    // Use stringstream to simulate binary file buffer deterministically
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    StudentRecord s1{"Nguyen Van A", 20, 8.5};
    StudentRecord s2{"Tran Thi B", 21, 9.0};

    // Write records
    stream.write(reinterpret_cast<const char*>(&s1), sizeof(StudentRecord));
    stream.write(reinterpret_cast<const char*>(&s2), sizeof(StudentRecord));

    // Check size using tellp/tellg
    stream.seekp(0, std::ios::end);
    std::streampos totalBytes = stream.tellp();
    std::size_t recordSize = sizeof(StudentRecord);
    std::size_t totalRecords = static_cast<std::size_t>(totalBytes) / recordSize;

    std::cout << "Record size: " << recordSize << " bytes\n";
    std::cout << "Total file size: " << totalBytes << " bytes\n";
    std::cout << "Record count: " << totalRecords << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <cstring>

struct Student {
    char name[32];
    int age;
    double score;
};

int main() {
    // Setup an in-memory stream representing a binary file
    std::stringstream file(std::ios::in | std::ios::out | std::ios::binary);
    const std::streamoff recordSize = sizeof(Student);

    // Populate 3 initial records
    Student s1{"Nguyen Van A", 19, 7.5};
    Student s2{"Le Thi B", 20, 8.0};
    Student s3{"Tran Van C", 21, 6.5};
    file.write(reinterpret_cast<const char*>(&s1), recordSize);
    file.write(reinterpret_cast<const char*>(&s2), recordSize);
    file.write(reinterpret_cast<const char*>(&s3), recordSize);

    // Inspect record 2 (1-based index)
    int targetIndex = 2;
    file.seekg((targetIndex - 1) * recordSize, std::ios::beg);
    Student current;
    file.read(reinterpret_cast<char*>(&current), recordSize);
    std::cout << "Original Record 2: " << current.name << ", Score: " << current.score << "\n";

    // Update score of record 2 in-place: position put pointer to record start
    file.seekp((targetIndex - 1) * recordSize, std::ios::beg);
    current.score = 9.75;
    file.write(reinterpret_cast<const char*>(&current), recordSize);

    // Re-read record 2 to verify update
    file.seekg((targetIndex - 1) * recordSize, std::ios::beg);
    Student updated;
    file.read(reinterpret_cast<char*>(&updated), recordSize);
    std::cout << "Updated Record 2: " << updated.name << ", Score: " << updated.score << "\n";

    return 0;
}
